package com.cpf.core.api.database; import org.springframework.core.env.Environment; import javax.sql.DataSource; import javax.naming.NamingException; public final class CpfDataSources {public static DataSource resolve(Environment e,String p)throws NamingException{String u=e.getProperty(p+".url","");if(u.isBlank())throw new NamingException("missing datasource "+p);return new DataSource(){public java.sql.Connection getConnection(){throw new UnsupportedOperationException();}public java.sql.Connection getConnection(String a,String b){throw new UnsupportedOperationException();}public <T>T unwrap(Class<T>c){throw new UnsupportedOperationException();}public boolean isWrapperFor(Class<?>c){return false;}public java.io.PrintWriter getLogWriter(){return null;}public void setLogWriter(java.io.PrintWriter w){}public void setLoginTimeout(int s){}public int getLoginTimeout(){return 0;}public java.util.logging.Logger getParentLogger(){return java.util.logging.Logger.getGlobal();}};}}
